            if len(ready) != 1:
                break
            item = ready[0]
            ordered.append(item)
            del remaining[item.task_id]
            previous = (item.task_id,)
        graph_mode = "dag" if remaining else "linear"
        if graph_mode == "dag":
            ordered = tasks
        ids = [r.capability.robot_id for r in robots]
